#[component]
fn Lcd(frame: String, on_key: EventHandler<&'static str>) -> Element {
    let mut on_key = on_key;
    let have_frame = !frame.is_empty();
    rsx! {
        div { class: "cam-lcd-bezel rounded-[12px] p-3 flex-1",
            div {
                class: "cam-lcd-screen relative rounded-[6px] overflow-hidden",
                style: "aspect-ratio: 4 / 3;",
                onclick: move |_| on_key.call("LCD"),
                if have_frame {
                    img {
                        class: "absolute inset-0 w-full h-full object-contain",
                        src: "{frame}",
                        alt: "firmware framebuffer",
                    }
                    div { class: "absolute right-2 bottom-2 rounded bg-black/55 px-2 py-[2px] text-[9px] text-white/80 tracking-wide",
                        "F · run-00ukkyz7"
                    }
                } else {
                    div { class: "absolute inset-0 flex flex-col items-center justify-center gap-2 text-white/70",
                        div { class: "text-[13px]", "未找到画面文件" }
                        div { class: "text-[10px] text-white/45 px-6 text-center break-all", "{FRAME_DEFAULT}" }
                    }
                }
            }
        }
    }
}

