#[component]
fn DpadButton(label: &'static str, pos: &'static str, on_key: EventHandler<&'static str>) -> Element {
    let mut on_key = on_key;
    let triangle = match label {
        "UP" => "cam-tri-up",
        "DOWN" => "cam-tri-down",
        "LEFT" => "cam-tri-left",
        _ => "cam-tri-right",
    };
    rsx! {
        div { class: "absolute {pos}",
            button {
                class: "w-[42px] h-[42px] flex items-center justify-center",
                onclick: move |_| on_key.call(label),
                div { class: "{triangle}" }
            }
            Readiness { label: "{label}", class: "absolute right-0 top-0" }
        }
    }
}

/// Solid dot when the guest has been driven with this control, hollow otherwise.
#[component]
fn Readiness(label: String, class: String) -> Element {
    let verified = is_verified(&label);
    let dot = if verified { "dot-ready" } else { "dot-unknown" };
    let title = if verified { "已动态验证" } else { "未验证，点击仅记录事件" };
    rsx! {
        span {
            class: "{class} w-[7px] h-[7px] rounded-full {dot} block",
            title: "{title}",
        }
    }
}

#[component]
fn StatusStrip() -> Element {
    rsx! {
        div { class: "cam-status h-[30px] flex items-center px-6 gap-6 text-[10px] text-[#3a3a3c]",
            span { "实心点=已动态验证；空心点=未验证，点击仅记录事件" }
            span { class: "text-[#6a6a6c]", "快捷键：方向键 / Enter / M / Delete / PageUp·PageDown / Esc" }
        }
    }
}

#[component]
fn LogPanel(log: Signal<Vec<String>>, mode: Signal<&'static str>) -> Element {
    let lines = log.read();
    rsx! {
        div { class: "bg-[#141517] border-t border-white/10 px-5 py-3",
            div { class: "flex items-center justify-between mb-2",
                div { class: "text-[10px] tracking-[0.16em] text-white/55", "后端未接入（原型）· 事件日志" }
                div { class: "text-[10px] text-white/35", "mode={mode}" }
            }
            div { class: "h-[96px] overflow-y-auto rounded bg-black/35 px-3 py-2",
                if lines.is_empty() {
                    div { class: "text-[11px] text-white/30", "点击机身上的控件开始记录…" }
                }
                for (i , line) in lines.iter().enumerate() {
                    div {
                        key: "{i}-{line}",
                        class: if i == 0 { "log-line log-latest text-[11px] text-white/90 py-[3px]" } else { "log-line text-[11px] text-white/55 py-[3px]" },
                        "{i:0>3}  {line}"
                    }
                }
            }
        }
    }
}
